sealed class GitpassException: kotlin.Exception() {
    
    class Generic(
        
        val v1: kotlin.String
        ) : GitpassException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<GitpassException> {
        override fun lift(error_buf: RustBuffer.ByValue): GitpassException = FfiConverterTypeGitpassError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeGitpassError : FfiConverterRustBuffer<GitpassException> {
    override fun read(buf: ByteBuffer): GitpassException {
        

        return when(buf.getInt()) {
            1 -> GitpassException.Generic(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: GitpassException): ULong {
        return when(value) {
            is GitpassException.Generic -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: GitpassException, buf: ByteBuffer) {
        when(value) {
            is GitpassException.Generic -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





/**
 * Transport failure. Carries no text from lower layers on purpose.
 */
sealed class HttpTransportException: kotlin.Exception() {
    
    class Timeout(
        ) : HttpTransportException() {
        override val message
            get() = ""
    }
    
    class Cancelled(
        ) : HttpTransportException() {
        override val message
            get() = ""
    }
    
    class TooLarge(
        ) : HttpTransportException() {
        override val message
            get() = ""
    }
    
    class Redirect(
        ) : HttpTransportException() {
        override val message
            get() = ""
    }
    
    class Transport(
        ) : HttpTransportException() {
        override val message
            get() = ""
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<HttpTransportException> {
        override fun lift(error_buf: RustBuffer.ByValue): HttpTransportException = FfiConverterTypeHttpTransportError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeHttpTransportError : FfiConverterRustBuffer<HttpTransportException> {
    override fun read(buf: ByteBuffer): HttpTransportException {
        

        return when(buf.getInt()) {
            1 -> HttpTransportException.Timeout()
            2 -> HttpTransportException.Cancelled()
            3 -> HttpTransportException.TooLarge()
            4 -> HttpTransportException.Redirect()
            5 -> HttpTransportException.Transport()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: HttpTransportException): ULong {
        return when(value) {
            is HttpTransportException.Timeout -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is HttpTransportException.Cancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is HttpTransportException.TooLarge -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is HttpTransportException.Redirect -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is HttpTransportException.Transport -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: HttpTransportException, buf: ByteBuffer) {
        when(value) {
            is HttpTransportException.Timeout -> {
                buf.putInt(1)
                Unit
            }
            is HttpTransportException.Cancelled -> {
                buf.putInt(2)
                Unit
            }
            is HttpTransportException.TooLarge -> {
                buf.putInt(3)
                Unit
            }
            is HttpTransportException.Redirect -> {
                buf.putInt(4)
                Unit
            }
            is HttpTransportException.Transport -> {
                buf.putInt(5)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Who is asking for a passkey (#477). Built by the app from Android's `CallingAppInfo`.
 */
sealed class PasskeyCaller {
    
    /**
     * A browser on the privileged allowlist; `origin` is the web origin the browser vouches for
     * (`CallingAppInfo.getOrigin(allowlist)`), never one taken from the request.
     */
    data class Browser(
        val `origin`: kotlin.String) : PasskeyCaller() {
        companion object
    }
    
    /**
     * Any other app: its package, the SHA-256 of its signing certificate (from the OS), and the
     * rpId's `/.well-known/assetlinks.json` as fetched by the app (may be empty when unavailable).
     */
    data class App(
        val `package`: kotlin.String, 
        val `certSha256`: kotlin.ByteArray, 
        val `assetLinksJson`: kotlin.String) : PasskeyCaller() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypePasskeyCaller : FfiConverterRustBuffer<PasskeyCaller>{
    override fun read(buf: ByteBuffer): PasskeyCaller {
        return when(buf.getInt()) {
            1 -> PasskeyCaller.Browser(
                FfiConverterString.read(buf),
                )
            2 -> PasskeyCaller.App(
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: PasskeyCaller) = when(value) {
        is PasskeyCaller.Browser -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`origin`)
            )
        }
        is PasskeyCaller.App -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`package`)
                + FfiConverterByteArray.allocationSize(value.`certSha256`)
                + FfiConverterString.allocationSize(value.`assetLinksJson`)
            )
        }
    }

    override fun write(value: PasskeyCaller, buf: ByteBuffer) {
        when(value) {
            is PasskeyCaller.Browser -> {
                buf.putInt(1)
                FfiConverterString.write(value.`origin`, buf)
                Unit
            }
            is PasskeyCaller.App -> {
                buf.putInt(2)
                FfiConverterString.write(value.`package`, buf)
                FfiConverterByteArray.write(value.`certSha256`, buf)
                FfiConverterString.write(value.`assetLinksJson`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






/**
 * @suppress
 */
public object FfiConverterOptionalULong: FfiConverterRustBuffer<kotlin.ULong?> {
    override fun read(buf: ByteBuffer): kotlin.ULong? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterULong.read(buf)
    }

    override fun allocationSize(value: kotlin.ULong?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterULong.allocationSize(value)
        }
    }

    override fun write(value: kotlin.ULong?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterULong.write(value, buf)
        }
    }
}




